{"command": "python3 -c "
# Read dictionary and build valid words
with open('/workdir/data/dict.txt', 'r') as f:
    all_lines = f.readlines()

valid_words = set()
for line in all_lines:
    line = line.strip()
    if line:
        # Filter: only lowercase alphabetic words
        if all(c.isalpha() and c.islower() for c in line):
            valid_words.add(line)

print(f'Total valid words: {len(valid_words)}')
""}
